"""Patch installed FFA; never imports hardware or writes Modbus registers."""
import ast
import sys
from pathlib import Path
from datetime import datetime
p=Path(sys.argv[1] if len(sys.argv)>1 else "/app/TLB_MODBUS.py")
src=p.read_text(encoding="utf-8")
replacements = {'_transact': ("FunctionDef(name='_transact', args=arguments(posonlyargs=[], args=[arg(arg='description'), arg(arg='fn')], vararg=arg(arg='args'), kwonlyargs=[arg(arg='retries')], kw_defaults=[Name(id='RETRIES', ctx=Load())], defaults=[]), body=[Expr(value=Constant(value='Run one Modbus transaction under _lock, retrying on failure.\\n\\n    The lock is taken and released inside the loop so the back-off sleep never\\n    happens while holding it.\\n    ')), Assign(targets=[Name(id='last_error', ctx=Store())], value=Constant(value=None)), For(target=Name(id='attempt', ctx=Store()), iter=Call(func=Name(id='range', ctx=Load()), args=[BinOp(left=Name(id='retries', ctx=Load()), op=Add(), right=Constant(value=1))], keywords=[]), body=[Try(body=[With(items=[withitem(context_expr=Name(id='_lock', ctx=Load()))], body=[Return(value=Call(func=Name(id='fn', ctx=Load()), args=[Starred(value=Name(id='args', ctx=Load()), ctx=Load())], keywords=[]))])], handlers=[ExceptHandler(type=Name(id='Exception', ctx=Load()), name='exc', body=[Assign(targets=[Name(id='last_error', ctx=Store())], value=Name(id='exc', ctx=Load())), If(test=Compare(left=Name(id='attempt', ctx=Load()), ops=[Lt()], comparators=[Name(id='retries', ctx=Load())]), body=[Expr(value=Call(func=Attribute(value=Name(id='time', ctx=Load()), attr='sleep', ctx=Load()), args=[Name(id='RETRY_DELAY', ctx=Load())], keywords=[]))], orelse=[])])], orelse=[], finalbody=[])], orelse=[]), Raise(exc=Call(func=Name(id='TLBCommunicationError', ctx=Load()), args=[Call(func=Attribute(value=Constant(value='{0} failed after {1} attempts: {2}'), attr='format', ctx=Load()), args=[Name(id='description', ctx=Load()), BinOp(left=Name(id='retries', ctx=Load()), op=Add(), right=Constant(value=1)), Name(id='last_error', ctx=Load())], keywords=[])], keywords=[]), cause=Name(id='last_error', ctx=Load()))], decorator_list=[], type_params=[])", 'def _transact(description, fn, *args, retries=RETRIES):\n    """Run one Modbus transaction under _lock, retrying on failure.\n\n    The lock is taken and released inside the loop so the back-off sleep never\n    happens while holding it.\n    """\n    last_error = None\n    for attempt in range(retries + 1):\n        try:\n            with _serial_transaction_lock():\n                return fn(*args)\n        except Exception as exc:      # noqa: BLE001 - pyserial/minimalmodbus\n            last_error = exc\n            if attempt < retries:\n                time.sleep(RETRY_DELAY)\n    raise TLBCommunicationError(\n        "{0} failed after {1} attempts: {2}".format(\n            description, retries + 1, last_error)\n    ) from last_error\n'), '_sample_counts': ("FunctionDef(name='_sample_counts', args=arguments(posonlyargs=[], args=[arg(arg='sample_grams'), arg(arg='division')], kwonlyargs=[], kw_defaults=[], defaults=[]), body=[Expr(value=Constant(value='Sample weight expressed in divisions, per manual page 16.')), Assign(targets=[Name(id='counts', ctx=Store())], value=Call(func=Name(id='int', ctx=Load()), args=[Call(func=Name(id='round', ctx=Load()), args=[BinOp(left=Name(id='sample_grams', ctx=Load()), op=Div(), right=Name(id='division', ctx=Load()))], keywords=[])], keywords=[])), If(test=Compare(left=Name(id='counts', ctx=Load()), ops=[LtE()], comparators=[Constant(value=0)]), body=[Raise(exc=Call(func=Name(id='TLBCalibrationError', ctx=Load()), args=[Call(func=Attribute(value=Constant(value='sample weight {0} g is below one division ({1})'), attr='format', ctx=Load()), args=[Name(id='sample_grams', ctx=Load()), Name(id='division', ctx=Load())], keywords=[])], keywords=[]))], orelse=[]), If(test=Compare(left=Name(id='counts', ctx=Load()), ops=[Gt()], comparators=[Constant(value=2147483647)]), body=[Raise(exc=Call(func=Name(id='TLBCalibrationError', ctx=Load()), args=[Constant(value='sample weight does not fit in 32 bits')], keywords=[]))], orelse=[]), Return(value=Name(id='counts', ctx=Load()))], decorator_list=[], type_params=[])", 'def _sample_counts(sample_grams, division):\n    """Encode sample display digits, with grams converted to instrument units."""\n    import math\n\n    sample_grams = float(sample_grams)\n    if not math.isfinite(sample_grams) or sample_grams <= 0:\n        raise TLBCalibrationError("Sample weight must be finite and positive")\n    unit = getUnit()\n    if unit not in ("g", "kg"):\n        raise TLBCalibrationError("Calibration requires unit g or kg")\n    sample = sample_grams if unit == "g" else sample_grams / 1000.0\n    counts = int(round(sample / _weight_decimal_scale(division)))\n    if counts <= 0:\n        raise TLBCalibrationError(\n            "sample weight {0} g is below one division ({1})".format(\n                sample_grams, division))\n    if counts > 0x7FFFFFFF:\n        raise TLBCalibrationError("sample weight does not fit in 32 bits")\n    return counts\n'), 'remote_calibration': ("FunctionDef(name='remote_calibration', args=arguments(posonlyargs=[], args=[arg(arg='step'), arg(arg='args')], kwonlyargs=[], kw_defaults=[], defaults=[]), body=[Expr(value=Constant(value='Guided calibration driven by calibrateScale.vue (steps 1..4).\\n\\n    1  start           - check the instrument is healthy, no write\\n    2  empty container - command 100, tare weight zero setting\\n    3  known sample    - write 40037/40038 then command 101, then verify\\n    4  finish          - command 99, persist to EEPROM\\n    ')), Global(names=['isCalibrating']), Assign(targets=[Name(id='is_belly', ctx=Store())], value=Compare(left=Name(id='args', ctx=Load()), ops=[Eq()], comparators=[Constant(value='belly')])), Assign(targets=[Name(id='inst', ctx=Store())], value=Call(func=Name(id='_for', ctx=Load()), args=[Name(id='is_belly', ctx=Load())], keywords=[])), Assign(targets=[Name(id='division', ctx=Store())], value=Call(func=Name(id='_load_division', ctx=Load()), args=[], keywords=[])), If(test=Compare(left=Name(id='step', ctx=Load()), ops=[Eq()], comparators=[Constant(value=1)]), body=[Assign(targets=[Name(id='status', ctx=Store())], value=Subscript(value=Call(func=Name(id='_read', ctx=Load()), args=[Name(id='inst', ctx=Load()), Name(id='REG_STATUS', ctx=Load()), Constant(value=1)], keywords=[]), slice=Constant(value=0), ctx=Load())), Assign(targets=[Name(id='faults', ctx=Store())], value=Call(func=Name(id='_faults', ctx=Load()), args=[Name(id='status', ctx=Load())], keywords=[])), If(test=Name(id='faults', ctx=Load()), body=[Raise(exc=Call(func=Name(id='TLBCalibrationError', ctx=Load()), args=[BinOp(left=Constant(value='cannot calibrate, instrument reports '), op=Add(), right=Call(func=Attribute(value=Constant(value=', '), attr='join', ctx=Load()), args=[Name(id='faults', ctx=Load())], keywords=[]))], keywords=[]))], orelse=[]), Expr(value=Call(func=Name(id='print', ctx=Load()), args=[Call(func=Attribute(value=Constant(value='Calibration start, status 0x{0:04X}'), attr='format', ctx=Load()), args=[Name(id='status', ctx=Load())], keywords=[])], keywords=[]))], orelse=[If(test=Compare(left=Name(id='step', ctx=Load()), ops=[Eq()], comparators=[Constant(value=2)]), body=[Expr(value=Call(func=Name(id='print', ctx=Load()), args=[Constant(value='Tare weight zero setting')], keywords=[])), Expr(value=Call(func=Name(id='_wait_for_stability', ctx=Load()), args=[Name(id='inst', ctx=Load())], keywords=[])), Expr(value=Call(func=Name(id='_write_command', ctx=Load()), args=[Name(id='inst', ctx=Load()), Name(id='CMD_CALIB_TARE', ctx=Load())], keywords=[]))], orelse=[If(test=Compare(left=Name(id='step', ctx=Load()), ops=[Eq()], comparators=[Constant(value=3)]), body=[Assign(targets=[Name(id='counts', ctx=Store())], value=Call(func=Name(id='_sample_counts', ctx=Load()), args=[Name(id='CALIB_SAMPLE_GRAMS', ctx=Load()), Name(id='division', ctx=Load())], keywords=[])), Expr(value=Call(func=Name(id='print', ctx=Load()), args=[Call(func=Attribute(value=Constant(value='Saving calibration point: {0} g = {1} counts'), attr='format', ctx=Load()), args=[Name(id='CALIB_SAMPLE_GRAMS', ctx=Load()), Name(id='counts', ctx=Load())], keywords=[])], keywords=[])), Expr(value=Call(func=Name(id='_wait_for_stability', ctx=Load()), args=[Name(id='inst', ctx=Load())], keywords=[])), Expr(value=Call(func=Name(id='_write_sample_weight', ctx=Load()), args=[Name(id='inst', ctx=Load()), Name(id='counts', ctx=Load())], keywords=[])), Expr(value=Call(func=Name(id='_write_command', ctx=Load()), args=[Name(id='inst', ctx=Load()), Name(id='CMD_SAVE_FIRST', ctx=Load())], keywords=[])), Expr(value=Call(func=Name(id='_verify_sample_consumed', ctx=Load()), args=[Name(id='inst', ctx=Load())], keywords=[]))], orelse=[If(test=Compare(left=Name(id='step', ctx=Load()), ops=[Eq()], comparators=[Constant(value=4)]), body=[Expr(value=Call(func=Name(id='print', ctx=Load()), args=[Constant(value='Persisting calibration to EEPROM')], keywords=[])), Expr(value=Call(func=Name(id='_write_command', ctx=Load()), args=[Name(id='inst', ctx=Load()), Name(id='CMD_SAVE_EEPROM', ctx=Load())], keywords=[])), Assign(targets=[Name(id='isCalibrating', ctx=Store())], value=Constant(value=False))], orelse=[Raise(exc=Call(func=Name(id='TLBCalibrationError', ctx=Load()), args=[Call(func=Attribute(value=Constant(value='unknown calibration step {0}'), attr='format', ctx=Load()), args=[Name(id='step', ctx=Load())], keywords=[])], keywords=[]))])])])])], decorator_list=[], type_params=[])", 'def remote_calibration(step, args):\n    """Guided calibration driven by calibrateScale.vue (steps 1..4).\n\n    1  start           - check the instrument is healthy, no write\n    2  empty container - command 100, tare weight zero setting\n    3  known sample    - write 40037/40038 then command 101, then verify\n    4  finish          - command 99, persist to EEPROM\n    """\n    global isCalibrating\n    is_belly = (args == "belly")\n    inst = _for(is_belly)\n    division = _load_division()\n\n    if step == 1:\n        _sample_counts(CALIB_SAMPLE_GRAMS, division)\n        status = _read(inst, REG_STATUS, 1)[0]\n        faults = _faults(status)\n        if faults:\n            raise TLBCalibrationError(\n                "cannot calibrate, instrument reports " + ", ".join(faults))\n        print("Calibration start, status 0x{0:04X}".format(status))\n\n    elif step == 2:\n        print("Tare weight zero setting")\n        _wait_for_stability(inst)\n        _write_command(inst, CMD_CALIB_TARE)\n\n    elif step == 3:\n        counts = _sample_counts(CALIB_SAMPLE_GRAMS, division)\n        print("Saving calibration point: {0} g = {1} counts".format(\n            CALIB_SAMPLE_GRAMS, counts))\n        _wait_for_stability(inst)\n        _write_sample_weight(inst, counts)\n        _write_command(inst, CMD_SAVE_FIRST)\n        _verify_sample_consumed(inst)\n\n    elif step == 4:\n        print("Persisting calibration to EEPROM")\n        _write_command(inst, CMD_SAVE_EEPROM)\n        isCalibrating = False\n\n    else:\n        raise TLBCalibrationError("unknown calibration step {0}".format(step))\n')}
helper = '@contextmanager\ndef _serial_transaction_lock():\n    """Wait cooperatively when Eventlet has patched time.sleep.\n\n    The lock is native because hardware loads before monkey_patch. Blocking\n    on it would freeze the hub while its owner waits for serial IO.\n    """\n    while not _lock.acquire(blocking=False):\n        time.sleep(0.001)\n    try:\n        yield\n    finally:\n        _lock.release()\n'
nodes={n.name:n for n in ast.parse(src).body if isinstance(n,ast.FunctionDef)}
if "_serial_transaction_lock" in nodes:
    raise SystemExit("Correctif deja present; aucun changement")
if "_weight_decimal_scale" not in nodes:
    raise SystemExit("Installer le correctif de lecture du poids en premier")
lines=src.splitlines(keepends=True)
edits=[]
for name,(expected,replacement) in replacements.items():
    node=nodes.get(name)
    if node is None or ast.dump(node,include_attributes=False)!=expected:
        raise SystemExit("Version inattendue; aucun changement: "+name)
    edits.append((node.lineno-1,node.end_lineno,replacement))
for start,end,replacement in sorted(edits,reverse=True):
    lines[start:end]=[replacement]
updated=''.join(lines)
updated=updated.replace('from threading import Lock','from threading import Lock\nfrom contextlib import contextmanager',1)
updated=updated.replace('def _transact(',helper+'\n\ndef _transact(',1)
ast.parse(updated)
backup=p.with_name(p.name+'.backup-controls-'+datetime.now().strftime('%Y%m%d-%H%M%S-%f'))
backup.write_bytes(p.read_bytes())
tmp=p.with_name(p.name+'.controls-fix.tmp')
tmp.write_text(updated,encoding='utf-8')
tmp.replace(p)
print('Correctif tare/calibration applique. Sauvegarde :',backup)
